from pathlib import Path
import subprocess,selectors,time,os,json,hashlib
journal=Path('examples/wd/proof_journals/pow_real_domains_2026-10-06.json')
frames=[('symbolic_roots_final', 'forall x R+:\n    x^(1/2)=x^(1/2)\n    x^(1/3)=x^(1/3)\n', True, False), ('native_exp_final', 'forall x R:\n    exp(x)=e^x\n    e^x=exp(x)\n', True, False), ('positive_real_carrier_final', 'forall a R+,t R:\n    a^t $in R\n', True, False), ('nonnegative_real_carrier_final', 'forall a R,t R+:\n    0<=a\n    =>:\n        a^t $in R\n', True, False), ('zero_positive_real_final', 'forall t R+:\n    0^t=0^t\n', True, False), ('integer_and_closed_domains_final', '0^0=1\n0^(0/3)=1\n0^3=0\n(-2)^(-3)=-1/8\ni^2=-1\n8^(1/3)=2\n', True, False), ('function_body_final', 'have fn real_power(a R+,t R) R=a^t\nreal_power(2,1/2)=2^(1/2)\n', True, False), ('power_log_inverse_final', 'forall a R+,t R:\n    a!=1\n    =>:\n        log(a,a^t)=t\n', True, False), ('missing_guard_final', 'forall a,t R:\n    a^t=a^t\n', False, False), ('zero_negative_final', '0^(-1/3)=0^(-1/3)\n', False, False)]
command=['target/release/litex','-strict','-session','-e','0=0']
p=subprocess.Popen(command,stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.PIPE,bufsize=0)
sel=selectors.DefaultSelector();sel.register(p.stdout,selectors.EVENT_READ)
pending=b''
def receive():
 global pending
 deadline=time.monotonic()+30
 while b'litex> ' not in pending:
  if time.monotonic()>deadline: raise TimeoutError('session frame timed out')
  for key,_ in sel.select(.5):
   chunk=os.read(key.fd,65536)
   if not chunk: raise RuntimeError('session ended before prompt')
   pending+=chunk
 before,pending=pending.split(b'litex> ',1)
 return before.decode()
try:
 initial=receive()
 j=json.loads(journal.read_text());j['final_session']={'command':command,'initial':initial,'binary_sha256':hashlib.sha256(Path(command[0]).read_bytes()).hexdigest()};journal.write_text(json.dumps(j,ensure_ascii=False,indent=2))
 for index,(name,body,expected,materialize) in enumerate(frames,1):
  code='sketch:\n'+''.join('    '+line+'\n' for line in body.splitlines())
  p.stdin.write((code+'\n').encode());p.stdin.flush()
  raw=receive();success='success\n' in raw and '"success": false' not in raw
  record={'id':f'B{index:03}','source_order':index,'intent':name,'candidate':code,'expected':expected,'success':success,'raw_output':raw,'materialize':materialize and success,'status':'accepted_unmaterialized' if materialize and success else 'diagnostic'}
  if record['materialize']: record['accepted_litex']=code
  j=json.loads(journal.read_text());j.setdefault('final_session_blocks',[]).append(record);journal.write_text(json.dumps(j,ensure_ascii=False,indent=2))
  print(name,success,'expected',expected,flush=True)
